import { useState } from 'react';
import { DsButton, DsCheckbox, DsPopover } from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';
export function Example() {
  const [active, setActive] = useState('unchecked');
  return <div style={{display:'flex', flexDirection:'column', alignItems:'flex-start', gap:16}}>
    <div style={{display:'flex', flexWrap:'wrap', gap:16, paddingBottom:180}}>
      <DsPopover label="Фильтр объектов" trigger={<DsButton tone="secondary" icon="filter_list">Фильтр</DsButton>}>
        {({close})=><div style={{display:'flex', flexDirection:'column', alignItems:'flex-start', gap:16}}>
          <DsCheckbox label="Только активные" state={active} onChange={setActive}/><DsButton onClick={close}>Готово</DsButton>
        </div>}
      </DsPopover>
      <DsButton tone="ghost" onClick={()=>setActive('unchecked')}>Сбросить фильтр</DsButton>
    </div>
    <p role="status">{active==='checked'?'Показаны только активные объекты.':'Показаны все объекты.'}</p>
  </div>;
}

inside-dialog:
import { useState } from 'react';
import { DsButton, DsDialog, DsPopover } from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';
export function Example() {
  const [dialog,setDialog] = useState(false);
  return <>
    <DsButton tone="secondary" onClick={()=>setDialog(true)}>Настроить отчёт</DsButton>
    <DsDialog open={dialog} title="Настройки отчёта" onClose={()=>setDialog(false)}>
      <DsPopover label="Справка о периоде" trigger={<DsButton tone="secondary">Как выбрать период</DsButton>}>
        {({close})=><div style={{display:'flex', flexDirection:'column', alignItems:'flex-start', gap:16}}>
          <p>Выберите период, за который нужно сравнить поездки объектов.</p><DsButton onClick={close}>Понятно</DsButton>
        </div>}
      </DsPopover>
    </DsDialog>
  </>;
}

controlled-panel:
import { useState } from 'react';
import { DsButton, DsPopover } from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';
export function Example() {
  const [open,setOpen] = useState(false), [saved,setSaved] = useState(false);
  return <div style={{display:'flex', flexDirection:'column', alignItems:'flex-start', gap:16}}>
    <div style={{display:'flex', justifyContent:'flex-end', alignSelf:'stretch', paddingBottom:180}}>
      <DsPopover label="Вид списка" open={open} onOpenChange={setOpen} align="end" width={280} trigger={props=><DsButton {...props} tone="secondary">Вид списка</DsButton>}>
        {({close})=><div style={{display:'flex', flexDirection:'column', alignItems:'flex-start', gap:16}}>
          <p>Запомнить текущий набор столбцов для следующих сеансов?</p>
          <DsButton onClick={()=>{setSaved(true);close()}}>Запомнить</DsButton>
        </div>}
      </DsPopover>
    </div>
    <p role="status">{saved?'Вид сохранён.':open?'Панель открыта.':'Панель закрыта.'}</p>
  </div>;
}
